initJs:
function(container, apiUrl, tables) {
  let autoRefreshInterval = null;
  let isAutoRefreshEnabled = false;

  // ステータス表示用の関数
  function getStatusBadge(status) {
    const statusMap = {
      '成功': { color: '#4ade80', text: '成功' },
      '失敗': { color: '#f87171', text: '失敗' },
      '警告': { color: '#fbbf24', text: '警告' },
      '実行中': { color: '#60a5fa', text: '実行中' }
    };
    const s = statusMap[status] || { color: '#9ca3af', text: status };
    return `<span style="background: ${s.color}; color: #1a2a40; padding: 2px 8px; border-radius: 12px; font-size: 0.8em; font-weight: bold;">${s.text}</span>`;
  }

  // 日時フォーマット関数
  function formatDateTime(dateStr) {
    if (!dateStr) return '-';
    const date = new Date(dateStr);
    return date.toLocaleString('ja-JP', {
      year: 'numeric', month: '2-digit', day: '2-digit',
      hour: '2-digit', minute: '2-digit', second: '2-digit'
    });
  }

  // サマリー更新関数
  function updateSummary(logs) {
    const total = logs.length;
    const success = logs.filter(log => log.処理ステータス === '成功').length;
    const error = logs.filter(log => log.処理ステータス === '失敗').length;
    const lastRun = logs.length > 0 ? 
      formatDateTime(logs.sort((a, b) => new Date(b.収集開始日時) - new Date(a.収集開始日時))[0].収集開始日時) : '-';

    container.querySelector('#summary-total').textContent = total;
    container.querySelector('#summary-success').textContent = success;
    container.querySelector('#summary-error').textContent = error;
    container.querySelector('#summary-last-run').textContent = lastRun;

    // エラー状況インジケーター更新
    const errorIndicator = container.querySelector('#error-indicator');
    const statusIcon = container.querySelector('#status-icon');
    const statusText = container.querySelector('#status-text');

    if (error > 0) {
      errorIndicator.style.borderLeftColor = '#f87171';
      statusIcon.style.background = '#f87171';
      statusText.textContent = `データ収集エラーが${error}件発生しています`;
    } else {
      errorIndicator.style.borderLeftColor = '#4ade80';
      statusIcon.style.background = '#4ade80';
      statusText.textContent = 'システム正常稼働中';
    }
  }

  // テーブル再描画関数
  function renderRows(rows) {
    const tbody = container.querySelector('#log-table-body');
    tbody.innerHTML = rows.map(row => `
      <tr data-id="${row.ログID || row.id}">
        <td>${formatDateTime(row.収集開始日時)}</td>
        <td>${row.データソース || ''}</td>
        <td>${row.データ種別 || ''}</td>
        <td>${getStatusBadge(row.処理ステータス)}</td>
        <td style="text-align: right;">${(row.収集件数 || 0).toLocaleString()}</td>
        <td style="text-align: right;">${(row.エラー件数 || 0).toLocaleString()}</td>
        <td style="text-align: right;">${row.処理時間秒 || 0}秒</td>
        <td style="text-align: right;">${row.データ品質スコア || 0}%</td>
        <td>
          <button class="action-btn secondary detail-btn" data-id="${row.ログID || row.id}">詳細</button>
          ${row.処理ステータス === '失敗' ? `<button class="action-btn retry-btn" data-id="${row.ログID || row.id}">再実行</button>` : ''}
        </td>
      </tr>
    `).join('');

    container.querySelector('#result-count').textContent = rows.length;
    updateSummary(rows);
  }

  // 初期データ表示
  renderRows(tables[12]?.records || []);

  // 検索・絞り込み機能
  container.querySelector('#btn-search').addEventListener('click', async () => {
    const dataSource = container.querySelector('#filter-data-source').value;
    const logLevel = container.querySelector('#filter-log-level').value;
    const startDate = container.querySelector('#filter-start-date').value;
    const endDate = container.querySelector('#filter-end-date').value;

    // 日付検証
    if (startDate && endDate && new Date(startDate) > new Date(endDate)) {
      alert('開始日は終了日より前の日付を設定してください');
      return;
    }

    try {
      const rows = await window.aivicApi.list(12);
      if (!rows) return;

      let filteredRows = rows.filter(row => {
        if (dataSource && row.データソース !== dataSource) return false;
        if (logLevel && row.処理ステータス !== logLevel) return false;
        if (startDate && new Date(row.収集開始日時) < new Date(startDate)) return false;
        if (endDate && new Date(row.収集開始日時) > new Date(endDate)) return false;
        return true;
      });

      renderRows(filteredRows);
    } catch (error) {
      console.error('検索エラー:', error);
    }
  });

  // CSVエクスポート機能
  container.querySelector('#btn-export').addEventListener('click', async () => {
    try {
      const rows = await window.aivicApi.list(12);
      if (!rows) return;

      const headers = ['収集日時', 'データソース', 'データ種別', 'ステータス', '収集件数', 'エラー件数', '処理時間', '品質スコア', 'エラーメッセージ'];
      const csvContent = '\uFEFF' + [
        headers.join(','),
        ...rows.map(row => [
          `"${formatDateTime(row.収集開始日時)}"`,
          `"${row.データソース || ''}"`,
          `"${row.データ種別 || ''}"`,
          `"${row.処理ステータス || ''}"`,
          row.収集件数 || 0,
          row.エラー件数 || 0,
          row.処理時間秒 || 0,
          row.データ品質スコア || 0,
          `"${(row.エラーメッセージ || '').replace(/"/g, '""')}"`
        ].join(','))
      ].join('\n');

      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = `data_collection_logs_${new Date().toISOString().split('T')[0]}.csv`;
      link.click();
    } catch (error) {
      console.error('エクスポートエラー:', error);
      alert('ログエクスポート処理が失敗しました');
    }
  });

  // 自動更新トグル
  container.querySelector('#btn-auto-refresh-toggle').addEventListener('click', () => {
    isAutoRefreshEnabled = !isAutoRefreshEnabled;
    const statusSpan = container.querySelector('#auto-refresh-status');

    if (isAutoRefreshEnabled) {
      statusSpan.textContent = '自動更新: ON';
      autoRefreshInterval = setInterval(async () => {
        const rows = await window.aivicApi.list(12);
        if (rows) renderRows(rows);
      }, 30000); // 30秒間隔
    } else {
      statusSpan.textContent = '自動更新: OFF';
      if (autoRefreshInterval) {
        clearInterval(autoRefreshInterval);
        autoRefreshInterval = null;
      }
    }
  });

  // ログ詳細表示
  function showLogDetail(logId) {
    window.aivicApi.list(12).then(rows => {
      if (!rows) return;

      const log = rows.find(r => (r.ログID || r.id) === logId);
      if (!log) return;

      container.querySelector('#detail-log-id').textContent = log.ログID || log.id;
      container.querySelector('#detail-data-source').textContent = log.データソース || '';
      container.querySelector('#detail-start-time').textContent = formatDateTime(log.収集開始日時);
      container.querySelector('#detail-end-time').textContent = formatDateTime(log.収集終了日時);
      container.querySelector('#detail-status').textContent = log.処理ステータス || '';
      container.querySelector('#detail-quality-score').textContent = `${log.データ品質スコア || 0}%`;
      container.querySelector('#detail-error-message').textContent = log.エラーメッセージ || '(エラーメッセージなし)';

      const retryBtn = container.querySelector('#btn-retry-log');
      if (log.処理ステータス === '失敗') {
        retryBtn.style.display = 'inline-block';
        retryBtn.onclick = () => retryLog(logId);
      } else {
        retryBtn.style.display = 'none';
      }

      container.querySelector('#log-detail-modal').classList.remove('hidden');
    });
  }

  // ログ再実行
  async function retryLog(logId) {
    try {
      const updated = await window.aivicApi.update(12, logId, {
        処理ステータス: '実行中',
        収集開始日時: new Date().toISOString(),
        エラーメッセージ: null
      });

      if (updated) {
        alert('ログの再実行を開始しました');
        container.querySelector('#log-detail-modal').classList.add('hidden');

        // 3秒後に成功状態に更新（実際の処理では外部システムとの連携が必要）
        setTimeout(async () => {
          await window.aivicApi.update(12, logId, {
            処理ステータス: '成功',
            収集終了日時: new Date().toISOString(),
            収集件数: Math.floor(Math.random() * 1000) + 100,
            エラー件数: 0,
            処理時間秒: Math.floor(Math.random() * 30) + 5,
            データ品質スコア: Math.floor(Math.random() * 20) + 80
          });

          const rows = await window.aivicApi.list(12);
          if (rows) renderRows(rows);
        }, 3000);
      }
    } catch (error) {
      console.error('再実行エラー:', error);
      alert('エラーログの再実行が失敗しました');
    }
  }

  // アラート設定表示
  container.querySelector('#btn-alert-settings').addEventListener('click', () => {
    container.querySelector('#alert-settings-modal').classList.remove('hidden');
  });

  // イベントデリゲーション
  container.addEventListener('click', (e) => {
    const detailBtn = e.target.closest('.detail-btn');
    const retryBtn = e.target.closest('.retry-btn');
    const closeModal = e.target.closest('#btn-close-modal, #btn-close-detail');
    const closeAlertModal = e.target.closest('#btn-close-alert-modal, #btn-cancel-alert-settings');

    if (detailBtn) {
      showLogDetail(detailBtn.dataset.id);
    } else if (retryBtn) {
      if (confirm('このログを再実行しますか？')) {
        retryLog(retryBtn.dataset.id);
      }
    } else if (closeModal) {
      container.querySelector('#log-detail-modal').classList.add('hidden');
    } else if (closeAlertModal) {
      container.querySelector('#alert-settings-modal').classList.add('hidden');
    }
  });

  // アラート設定保存
  container.querySelector('#btn-save-alert-settings').addEventListener('click', () => {
    const enabled = container.querySelector('#alert-error-enabled').checked;
    const email = container.querySelector('#alert-email').value;
    const frequency = container.querySelector('#alert-frequency').value;

    if (enabled && !email) {
      alert('通知先メールアドレスを入力してください');
      return;
    }

    // 設定保存（実際の実装では設定テーブルに保存）
    localStorage.setItem('alertSettings', JSON.stringify({ enabled, email, frequency }));
    alert('アラート通知設定を保存しました');
    container.querySelector('#alert-settings-modal').classList.add('hidden');
  });

  // 設定読み込み
  const savedSettings = localStorage.getItem('alertSettings');
  if (savedSettings) {
    const settings = JSON.parse(savedSettings);
    container.querySelector('#alert-error-enabled').checked = settings.enabled;
    container.querySelector('#alert-email').value = settings.email;
    container.querySelector('#alert-frequency').value = settings.frequency;
  }
}
